mapper.select:
select id, generation, workflow_definition_id, source_type, source_key, biz_date,
       occurrence_status, expected_at, due_at, trigger_request_id
  from batch.expected_work_occurrence
 where tenant_id = #{tenantId}
   and calendar_code = #{calendarCode}
   and biz_date = #{bizDate}
   and occurrence_status in ('EXPECTED', 'ARRIVED')
 order by id
   for update

mapper.update:
update batch.expected_work_occurrence
   set occurrence_status = #{newStatus},
       trigger_request_id = coalesce(#{triggerRequestId}, trigger_request_id),
       updated_at = CURRENT_TIMESTAMP
 where tenant_id = #{tenantId}
   and calendar_code = #{calendarCode}
   and workflow_definition_id = #{workflowDefinitionId}
   and source_type = #{sourceType}
   and source_key = #{sourceKey}
   and biz_date = #{bizDate}
   and generation = coalesce(
       #{generation},
       (select max(latest.generation)
          from batch.expected_work_occurrence latest
         where latest.tenant_id = #{tenantId}
           and latest.calendar_code = #{calendarCode}
           and latest.workflow_definition_id = #{workflowDefinitionId}
           and latest.source_type = #{sourceType}
           and latest.source_key = #{sourceKey}
           and latest.biz_date = #{bizDate}))
   and occurrence_status = #{expectedStatus}

mapper.select:
select count(*)
  from batch.expected_work_occurrence
 where tenant_id = #{tenantId}
   and calendar_code = #{calendarCode}
   and biz_date = #{bizDate}
   and occurrence_status in ('EXPECTED', 'ARRIVED')

select id, generation, workflow_definition_id, source_type, source_key, biz_date,
       occurrence_status, expected_at, due_at, trigger_request_id
  from batch.expected_work_occurrence
 where tenant_id = #{tenantId}
   and calendar_code = #{calendarCode}
   and biz_date = #{bizDate}
   and occurrence_status = 'EXPECTED'
   and due_at is not null
   and due_at <= #{now}
   and missing_input_alerted_at is null
 order by due_at, id
 limit #{limit}
   for update skip locked
